public void initializeEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    super(_entityCtx, _dataSourceCtx);
    switch (_dataSourceCtx.name())
    {
        case dataEntityDataSourceStr(GUPVendPriceAdmTransEntity, InventDim) :
            _dataSourceCtx.setDataSaved(true);
            _dataSourceCtx.setDatabaseOperation(DataEntityDatabaseOperation::Update);
            break;
    }
}

public boolean insertEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    boolean ret;
    switch (_dataSourceCtx.name())
    {
        case dataEntityDataSourceStr(GUPVendPriceAdmTransEntity, GUPVendPriceAdmTrans) :
            GUPVendPriceAdmTrans trans = _dataSourceCtx.getBuffer();
            GUPVendPriceAdmTable table = GUPVendPriceAdmTable::find(trans.JournalNum);
            if (!table)
            {
                throw error(strFmt("@GlobalUnifiedPricing:GUPVendPriceAdmTable_NotExisting", trans.JournalNum));
                return false;
            }
            trans.AccountCode = table.AccountCode;
            trans.AccountRelation = table.AccountRelation;
            InventDim inventDim;
            inventDim.configId = this.Configuration;
            inventDim.InventSizeId = this.Size;
            inventDim.InventColorId = this.Color;
            inventDim.InventStyleId = this.Style;
            inventDim.InventSiteId = this.Site;
            inventDim.InventLocationId = this.Warehouse;
            inventDim.wMSLocationId = this.Location;
            inventDim.InventStatusId = this.InventoryStatus;
            inventDim.LicensePlateId = this.LicensePlate;
            inventDim.inventBatchId = this.BatchNumber;
            inventDim.inventSerialId = this.SerialNumber;
            inventDim.InventOwnerId_RU = this.Owner;
            inventDim.InventProfileId_RU = this.ProductProfile;
            inventDim.InventGtdId_RU = this.ProductGtd;
            inventDim = InventDim::findOrCreate(inventDim);
            inventDim.update();
            trans.InventDimId = inventDim.inventDimId;
            break;
    }
    ret = super(_entityCtx, _dataSourceCtx);
    return ret;
}

public boolean updateEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    boolean ret;
    switch (_dataSourceCtx.name())
    {
        case dataEntityDataSourceStr(GUPVendPriceAdmTransEntity, GUPVendPriceAdmTrans) :
            GUPVendPriceAdmTrans trans = _dataSourceCtx.getBuffer();
            GUPVendPriceAdmTable table = GUPVendPriceAdmTable::find(trans.JournalNum);
            if (!table)
            {
                throw error("Vendor list price table does not exist");
                return false;
            }
            InventDim inventDim;
            inventDim.configId = this.Configuration;
            inventDim.InventSizeId = this.Size;
            inventDim.InventColorId = this.Color;
            inventDim.InventStyleId = this.Style;
            inventDim.InventSiteId = this.Site;
            inventDim.InventLocationId = this.Warehouse;
            inventDim.wMSLocationId = this.Location;
            inventDim.InventStatusId = this.InventoryStatus;
            inventDim.LicensePlateId = this.LicensePlate;
            inventDim.inventBatchId = this.BatchNumber;
            inventDim.inventSerialId = this.SerialNumber;
            inventDim.InventOwnerId_RU = this.Owner;
            inventDim.InventProfileId_RU = this.ProductProfile;
            inventDim.InventGtdId_RU = this.ProductGtd;
            inventDim = InventDim::findOrCreate(inventDim);
            trans.InventDimId = inventDim.inventDimId;
            inventDim.update();
            break;
    }
    ret = super(_entityCtx, _dataSourceCtx);

    return ret;
}
